// Variant C: "Sequence-first": the film strip is the one surface. Review, compare and fixing all happen on it.
// Takes preview in place inside the cut; cost is a scope-then-invoke ticket under the strip.
ACT.tog = d => { const p = S.ui.pick || (S.ui.pick = []); const id = +d.shot; S.ui.pick = p.includes(id) ? p.filter(x => x !== id) : [...p, id]; S.ui.pickBy = null; };
ACT.quick = d => { S.ui.pickBy = d.by; S.ui.pick = S.shots.filter(s => d.by === 'gaps' ? (!s.sel && !liveTakes(s).length && !jobOf(s)) : d.by === 'ood' ? (s.ood && !s.ood.kept) : true).map(s => s.id); };
ACT.clr = () => { S.ui.pick = []; S.ui.pickBy = null; };
ACT.genSel = () => request(S.ui.pick.map(id => genItem(shot(id), S.ui.model)), { bulkFilter: S.ui.pickBy === 'ood' });
ACT.prev = d => { S.ui.prev2 = S.ui.prev; S.ui.prev = +d.take; };
ACT.flip = () => { const s = cur(); const a = previewId(s); const b = S.ui.prev2 || (a === s.sel ? (liveTakes(s).find(t => t.id !== a) || {}).id : s.sel); S.ui.prev = b; S.ui.prev2 = a; };
ACT.sc = d => { S.ui.sc = +d.n; };
const VC = (() => {
  const ticket = () => {
    const c = S.ui.confirm, pk = S.ui.pick || [];
    if (c) return `<div style="border-left:3px solid var(--ac);background:var(--p2);padding:10px 14px;margin:10px 0;border-radius:0 8px 8px 0"><div class="row"><b>${c.ev.count} generation${c.ev.count > 1 ? 's' : ''} · ${c.ev.total ? 'about ' + money(c.ev.total) : 'price unavailable'}</b><span class="mu xs">largest ${money(c.ev.largest)} · ${money(Math.max(0, CAP - S.spent))} left today</span><span class="grow"></span><button class="pri" data-act="go_confirm">Start</button><button class="ghost" data-act="no_confirm">Not now</button></div><div class="xs mu" style="margin-top:4px">Why you're asked: ${c.ev.reasons.join(' · ')}.</div></div>`;
    if (!pk.length) return `<div class="xs mu" style="margin:10px 0">Select shots on the strip to act on them, or use a quick selection. The price shows before anything starts.</div>`;
    const items = pk.map(id => genItem(shot(id), S.ui.model)); const ev = evaluate(items, { bulkFilter: S.ui.pickBy === 'ood' });
    return `<div class="row" style="margin:10px 0;padding:8px 12px;background:var(--p1);border:1px solid var(--ln);border-radius:8px"><b>${pk.length} shot${pk.length > 1 ? 's' : ''} selected</b><span class="grow"></span>${modelSelect()}<button class="pri" data-act="genSel">${S.ui.pickBy === 'ood' ? 'Regenerate' : 'Generate'} · ${ev.total ? money(ev.total) : 'price unavailable'}${ev.reasons.length ? ' · asks first' : ''}</button><button class="ghost sm" data-act="clr">Clear</button></div>`;
  };
  const cell = (x, focus, review) => {
    const s = x.shot; const stt = s.mock ? (s.sel ? 'selected' : 'missing') : state(s); const isFocus = focus === s.id && !s.mock;
    const take = isFocus && previewId(s) ? s.takes.find(t => t.id === previewId(s)) : x.take; const previewing = isFocus && previewId(s) && previewId(s) !== s.sel;
    const picked = (S.ui.pick || []).includes(s.id);
    const body = s.mock ? `<div class="poster" style="background-image:${s.sel ? poster(s.hue, s.id) : 'none'};${s.sel ? '' : 'background:#1b2027'}"></div>`
      : stt === 'failed' ? `<div class="slate" style="flex-direction:column;gap:3px;border-color:#6b4545"><span class="xs" style="color:var(--bad)">Failed</span><button class="sm" data-act="retry" data-shot="${s.id}">Retry ${money(priceOf(s, s.failed.model))}</button></div>`
      : stt === 'generating' ? `<div class="slate" style="flex-direction:column;gap:5px"><span class="xs">${s.batchPartial ? s.batchPartial.done + ' of ' + s.batchPartial.total + ' parts' : 'Generating'}</span>${jobOf(s) ? `<div class="prog" style="width:70%"><i style="width:${jobOf(s).progress}%"></i></div>` : ''}</div>`
        : take ? `<div class="poster ${S.play.on && cu0 && cu0.shot === s ? 'kb' : ''}" style="background-image:${posterOf(s, take)}"><span class="tc">${take.n ? 'Take ' + take.n : ''}</span>${previewing ? '<span class="tl">previewing</span>' : ''}</div>`
          : `<div class="slate" style="flex-direction:column;gap:2px"><span class="xs">${stt === 'needs-pick' ? 'needs a pick' : 'no take'}</span></div>`;
    const act = review ? `data-act="seek" data-t="${x.start}"` : s.mock ? '' : `data-act="go" data-view="shot" data-shot="${s.id}" data-keep="1"`;
    return `<div style="width:${review ? Math.max(112, x.d * 22) : 138}px;flex:none"><div ${act} style="cursor:pointer;border-radius:8px;padding:3px;${isFocus ? 'background:#25324a;' : ''}${cu0 && cu0.shot === s && S.play.on ? 'outline:2px solid #fff;' : ''}">${body}</div>
    <div class="row xs" style="margin-top:3px;padding:0 3px"><input type="checkbox" ${picked ? 'checked' : ''} ${s.mock ? 'disabled' : ''} data-act="tog" data-shot="${s.id}"><b>${s.label}</b>${oodDot(s).replace('data-act="oodpop"', 'data-x')}<span class="grow"></span>${s.mock ? '' : `<span class="chip ${stateCls[stt]}" style="padding:0 5px">${{ final: '🔒', selected: '✓', 'needs-pick': '?', missing: '–', failed: '!', generating: '…' }[stt]}</span>`}</div></div>`;
  };
  let cu0 = null;
  const scenes = () => `<div class="row" style="flex-wrap:wrap;gap:3px;margin-bottom:8px">${[...Array(22)].map((_, i) => { const n = i + 1; return `<button class="sm ${(S.ui.sc || 7) === n ? 'pri' : ''}" style="padding:1px 6px" data-act="sc" data-n="${n}">${n}</button>`; }).join('')}</div>`;
  const stripItems = () => { const sc = S.ui.sc || 7; const all = playItems(); return S.scope === 'film' && S.view === 'review' ? all.filter(x => (x.shot.scene || 7) === sc) : (sc === 7 ? all : (() => { const f = filmShots().filter(x => x.scene === sc); let st = 0; return f.map(s => { const o = { shot: s, take: null, start: st, d: s.dur, gap: !s.sel }; st += s.dur; return o; }); })()); };
  function lane(s) {
    const live = liveTakes(s); const insp = previewId(s); const p = priceOf(s, S.ui.model); const job = jobOf(s);
    const t = s.takes.find(x => x.id === insp);
    return `<div style="background:var(--p1);border:1px solid var(--ln);border-radius:10px;padding:12px;margin-top:6px"><div class="row"><b>${s.label} · ${s.title}</b>${oodDot(s)}${stateChip(s)}<span class="grow"></span>${S.returnTo ? '<button class="sm" data-act="back">↩ Back to review</button>' : ''}</div><div class="xs mu">${s.plan}</div>${oodPop(s)}
    <div class="row" style="margin-top:10px;align-items:flex-start;gap:14px"><div style="width:44%;flex:none"><div class="xs mu" style="margin-bottom:4px">TAKES · click to preview inside the cut above</div><div class="row" style="flex-wrap:wrap;gap:6px">${live.map(x => `<div style="width:92px"><div class="poster ${x.id === s.sel ? 'sel' : ''}" style="background-image:${posterOf(s, x)};cursor:pointer;${x.id === insp ? 'box-shadow:0 0 0 2px #fff6' : ''}" data-act="prev" data-take="${x.id}"><span class="tc">T${x.n}</span></div><div class="xs mu">${x.id === s.sel ? (s.final ? '🔒 final' : 'picked') : ''}${x.late ? 'arrived after cancel' : ''}</div></div>`).join('') || '<span class="xs mu">No takes yet.</span>'}</div>
    ${rejTakes(s).length ? `<div class="xs mu" style="margin-top:6px">Rejected: ${rejTakes(s).map(r => `T${r.n} <button class="sm ghost" data-act="restore" data-shot="${s.id}" data-take="${r.id}">restore</button>`).join(' ')}</div>` : ''}
    ${t ? `<div class="row" style="margin-top:8px;flex-wrap:wrap">${s.sel === t.id ? `<span class="chip ok">Picked</span><button class="sm" data-act="final" data-shot="${s.id}">${s.final ? 'Unlock final' : 'Mark final'}</button>` : `<button class="pri sm" data-act="select" data-shot="${s.id}" data-take="${t.id}">Pick take ${t.n}</button>`}<button class="sm" data-act="flip" title="Flip between this and the pick, in place">⇄ Flip with ${s.sel && s.sel !== t.id ? 'pick' : 'another'}</button><button class="sm" data-act="reject" data-shot="${s.id}" data-take="${t.id}">Reject</button><button class="sm ghost" data-act="playctx" data-shot="${s.id}" data-take="${t.id}">▶ Play in context</button></div>` : ''}</div>
    <div class="grow col"><div class="xs mu">MAKE</div><div class="row">${modelSelect()}</div>${guidanceBox()}<button class="pri" data-act="gen" data-shot="${s.id}" ${job ? 'disabled' : ''}>${live.length ? 'Regenerate' : 'Generate'} · ${p == null ? 'price unavailable' : money(p)}${s.long ? ' · ' + s.long + ' parts' : ''}</button>${job ? `<div class="row"><div class="prog grow"><i style="width:${job.progress}%"></i></div><button class="sm ghost" data-act="cancel" data-job="${job.id}">Cancel</button></div>` : ''}${s.failed ? `<div class="note">${s.failed.reason} ${s.failed.billed === 'maybe' ? 'You may have been charged.' : ''} <button class="sm" data-act="retry" data-shot="${s.id}">Retry ${money(priceOf(s, s.failed.model))}</button></div>` : ''}${s.batchPartial && !job ? `<div class="note">${s.batchPartial.done} of ${s.batchPartial.total} parts made. No take until assembled.</div>` : ''}
    <button class="ghost sm" style="align-self:flex-start" data-act="ui" data-key="inspect" data-val="">${S.ui.inspect ? '▾' : '▸'} Prompt and references</button>${S.ui.inspect ? inspectBlock(s) : ''}</div></div></div>`;
  }
  function common(review) {
    const it = stripItems(); const tot = totalDur() || 1; cu0 = playItems()[currentIndex(playItems())]; const focus = review ? null : S.shotId;
    const stage = S.ui.sc && S.ui.sc !== 7 ? '<div class="note">Mock scene: only scene 7 is live in this prototype.</div>' : `<div style="width:${review ? 'min(760px,100%)' : 'min(460px,100%)'}">${stageHTML(S.play.items ? cu0 : (review ? cu0 : (() => { const s = cur(); const t = s.takes.find(x => x.id === previewId(s)); return t ? { shot: s, take: t } : { gap: true, shot: s }; })()), `<span class="tl">${S.play.items || review ? tc(S.play.t) + ' / ' + tc(tot) : 'in the cut'}</span>`)}<div class="row" style="margin-top:6px"><button class="pri" data-act="play">${S.play.on ? '❚❚ Pause' : '▶ Play scene'}</button><button data-act="nextitem" data-dir="-1">⏮</button><button data-act="nextitem" data-dir="1">⏭</button><label class="row xs mu"><input type="checkbox" ${S.play.skipGaps ? 'checked' : ''} data-act="skipgaps">skip gaps</label>${S.play.items ? '<button class="sm" data-act="endctx">Stop context preview</button>' : ''}<span class="grow"></span>${review && cu0 && !cu0.shot.mock ? `<button data-act="go" data-view="shot" data-shot="${cu0.shot.id}" data-ret="1">Fix ${cu0.shot.label} ↗</button>` : ''}</div></div>`;
    const quick = `<div class="row xs mu" style="margin:8px 0 4px">Select: <button class="sm" data-act="quick" data-by="gaps">gaps</button><button class="sm" data-act="quick" data-by="ood">possibly out of date</button><button class="sm" data-act="quick" data-by="all">all in scene</button><span class="grow"></span><button class="sm" data-act="genFilm">Whole film…</button></div>`;
    const strip = `<div class="row" style="align-items:flex-start;gap:6px;overflow:auto;padding-bottom:4px;position:relative">${it.map(x => cell(x, focus, review)).join('')}${(S.ui.sc || 7) === 7 && !review ? '' : ''}</div>`;
    return { stage, quick, strip };
  }
  function renderShot(s) {
    const { stage, quick, strip } = common(false);
    return `<div style="padding:14px 16px"><div class="row" style="align-items:flex-start;gap:16px">${stage}<div class="grow col xs mu"><div class="row"><b style="color:var(--tx);font-size:14px">Scene 7 · The Harbour Office</b></div><div>${sceneStats().sel} of ${sceneStats().n} shots have a picked take · ${sceneStats().ood} possibly out of date · ${tc(sceneStats().runtime)} planned</div><div>The strip is the cut. Click a take below to see it inside the cut, with the shots on either side. Nothing is picked until you pick it.</div><div class="row"><button data-act="go" data-view="review" data-scope="scene">Open in Review &amp; Export ↗</button></div></div></div>
    ${scenes().replace(/^/, '<div class="xs mu" style="margin:12px 0 4px">SCENES</div>')}${quick}${strip}${ticket()}${lane(s)}</div>`;
  }
  function renderReview() {
    const { stage, quick, strip } = common(true); const film = S.scope === 'film';
    return `<div class="tabs"><button class="${!film ? 'on' : ''}" data-act="go" data-view="review" data-scope="scene">Scene</button><button class="${film ? 'on' : ''}" data-act="go" data-view="review" data-scope="film">Whole film</button></div><div style="padding:14px 16px">${stage}${film ? `<div class="xs mu" style="margin:14px 0 4px">PICK A SCENE (22). Scene 7 is live; others are mock.</div>${scenes()}` : '<div style="height:12px"></div>'}${strip}${ticket()}<div class="xs mu" style="margin-top:6px">Block width is runtime. Hatched = no selected take (plays as a 2 s slate). Dot = possibly out of date. Click a block to play from it; Fix opens that shot.</div></div>`;
  }
  return { renderShot, renderReview };
})();
